# Let me extract data from the table in a different way
# Looking at the text file around the NET CAPITAL MOVEMENT rows

with open('/app/resources/treasury_bulletin_1939_04_page_61.txt', 'r') as f:
    lines = f.readlines()

in_net_section = False
for i, line in enumerate(lines):
    if 'NET CAPITAL MOVEMENT:' in line:
        in_net_section = True
    if in_net_section:
        # Look for the January 1939 weekly rows
        if 'Jan. 18' in line or 'Jan. 25' in line:
            print(f'Line {i}: {line[:200]}')
            if '</tr>' in line:
                in_net_section = False
"
